edit('frontend/src/pages/OperationsDesk.tsx',lambda s:s.replace(" const botPending=useRef", " const [choices,setChoices]=useState<string[]>([])\n const [conversationId]=useState(()=>{const key='operations-assistant:'+embeddedClient;const id=sessionStorage.getItem(key)||crypto.randomUUID();sessionStorage.setItem(key,id);return id})\n const botPending=useRef").replace("{...botPending.current,clientId:","{...botPending.current,conversationId,clientId:").replace('setBotReply(r.reply);','setBotReply(r.reply);setChoices(r.choices||[]);').replace('{botReply&&<p className="op-reply" role="status">{botReply}</p>}', '{botReply&&<p className="op-reply" role="status">{botReply}</p>}{choices.length>0&&<div className="op-actions">{choices.map((choice,i)=><button key={i} disabled={busy} onClick={()=>setBotText(String(i+1))}>{choice}</button>)}</div>}<button className="office-secondary" onClick={()=>setBotText(\'התחל מחדש\')}>שיחה חדשה / לקוח אחר</button>').replace('אין שליחה לוואטסאפ.</p>', 'אם ההוראה לא ברורה, העוזר ישאל על הלקוח, המוצר והפעולה. אפשר לענות בשם או במספר. אין שליחה לוואטסאפ.</p>'))
